const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const states = ee.FeatureCollection('USGS/KATCR/US_STATES_PRE2000');
  const california = states.filter(ee.Filter.eq('STATE_NAME', 'California')).geometry();
  const mississippi = states.filter(ee.Filter.eq('STATE_NAME', 'Mississippi')).geometry();

  const startDate = '2005-07-09'; // Covers July 12-16
  const endDate = '2005-07-24'; // Covers July 17-19

  const scale = 5000; // Use a coarse scale for regional average to avoid memory issues

  // Function to mask clouds based on MOD11A2 QC band
  function maskLST(image) {
    const lstDay = image.select('LST_Day_1km');
    const qc = image.select('QC_Day');

    // Bits 0-1 are "LST quality": 00 = good quality, 01 = marginal quality
    // We want good quality (00)
    const lstQuality = qc.rightShift(0).bitwiseAnd(3); // Extract bits 0-1

    // Apply quality mask
    const maskedLST = lstDay.updateMask(lstQuality.eq(0));

    // Scale LST to Kelvin (0.02 is the scale factor)
    return maskedLST.multiply(0.02);
  }

  // 2. Data Acquisition & Check
  const lstCollection = ee.ImageCollection('MODIS/061/MOD11A2')
    .filterDate(startDate, endDate)
    .select(['LST_Day_1km', 'QC_Day'])
    .map(maskLST);

  // Check collection sizes
  const ca_col_size = lstCollection.filterBounds(california).size().getInfo();
  const ms_col_size = lstCollection.filterBounds(mississippi).size().getInfo();

  if (ca_col_size === 0 || ms_col_size === 0) {
    console.log(`California Images: ${ca_col_size}`);
    console.log(`Mississippi Images: ${ms_col_size}`);
    console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
    return;
  }

  // Mosaic and take the mean over the period for each state
  const ca_mosaic = lstCollection.filterBounds(california).mean();
  const ms_mosaic = lstCollection.filterBounds(mississippi).mean();

  // 3. Processing (Calculate pixel count to detect C2)
  const ca_pixels_dict = ca_mosaic.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: california,
    scale: scale,
    maxPixels: 1e9
  });
  const ca_valid_pixels = ca_pixels_dict.get('LST_Day_1km').getInfo();

  const ms_pixels_dict = ms_mosaic.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mississippi,
    scale: scale,
    maxPixels: 1e9
  });
  const ms_valid_pixels = ms_pixels_dict.get('LST_Day_1km').getInfo();

  if (ca_valid_pixels === 0 || ms_valid_pixels === 0) {
    console.log(`CA Valid Pixels: ${ca_valid_pixels}`);
    console.log(`MS Valid Pixels: ${ms_valid_pixels}`);
    console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
    return;
  }

  // 4. Calculation
  const ca_lst_dict = ca_mosaic.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: california,
    scale: scale,
    maxPixels: 1e9
  });
  const ca_mean_lst_kelvin = ca_lst_dict.get('LST_Day_1km').getInfo();

  const ms_lst_dict = ms_mosaic.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mississippi,
    scale: scale,
    maxPixels: 1e9
  });
  const ms_mean_lst_kelvin = ms_lst_dict.get('LST_Day_1km').getInfo();

  // 5. Validation & Final Answer
  if (ca_mean_lst_kelvin === null || ms_mean_lst_kelvin === null ||
      isNaN(ca_mean_lst_kelvin) || isNaN(ms_mean_lst_kelvin)) {
    console.log(`CA LST: ${ca_mean_lst_kelvin}, MS LST: ${ms_mean_lst_kelvin}`);
    console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
    return;
  }

  // Convert Kelvin to Celsius for readability
  const ca_mean_lst_celsius = ca_mean_lst_kelvin - 273.15;
  const ms_mean_lst_celsius = ms_mean_lst_kelvin - 273.15;

  console.log(`CA LST (K): ${ca_mean_lst_kelvin.toFixed(2)} (Val Pixels: ${ca_valid_pixels})`);
  console.log(`MS LST (K): ${ms_mean_lst_kelvin.toFixed(2)} (Val Pixels: ${ms_valid_pixels})`);
  console.log(`CA LST (C): ${ca_mean_lst_celsius.toFixed(2)}`);
  console.log(`MS LST (C): ${ms_mean_lst_celsius.toFixed(2)}`);

  if (ca_mean_lst_kelvin > ms_mean_lst_kelvin) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
